/**
 * JSON path helpers used by file-based adapters.
 * @module functions/jsondb
 */

/**
 * Sets a nested value on an object.
 * @param {string} path Nested key path.
 * @param {*} value Value to set.
 * @param {Object} obj Target object.
 * @param {string} seperator Path separator.
 * @returns {void}
 */
module.exports.set = function (path, value, obj, seperator) {
    var schema = obj;
    var pList = path.split(seperator);
    var len = pList.length;
    for(var i = 0; i < len-1; i++) {
        var elem = pList[`${i}`];
        if(schema[`${elem}`] === null || typeof schema[`${elem}`] !== "object" || Array.isArray(schema[`${elem}`])) {
          schema[`${elem}`] = {};
        }
        schema = schema[`${elem}`];
    }
    schema[pList[`${len-1}`]] = value;
};

/**
 * Gets a nested value from an object.
 * @param {Object} obj Source object.
 * @param {string} seperator Path separator.
 * @param {...string} data Path segments.
 * @returns {*|undefined}
 */
module.exports.get = function(obj, seperator, ...data) {
  return data.reduce(function(acc, key) {
    if (acc === null || typeof acc === "undefined") {
      return undefined;
    }
    return acc[`${key}`];
  }, obj);
};

/**
 * Checks whether a nested path exists on an object.
 * @param {Object} obj Source object.
 * @param {string} seperator Path separator.
 * @param {...string} data Path segments.
 * @returns {boolean}
 */
module.exports.has = function(obj, seperator, ...data) {
  var schema = obj;
  for (var i = 0; i < data.length; i++) {
    if (schema === null || typeof schema === "undefined" || !Object.prototype.hasOwnProperty.call(Object(schema), data[`${i}`])) {
      return false;
    }
    schema = schema[`${data[i]}`];
  }
  return true;
};

/**
 * Removes a nested value from an object.
 * @param {Object} obj Source object.
 * @param {string|string[]} path Nested path or path segments.
 * @param {string} seperator Path separator.
 * @returns {void}
 */
module.exports.remove = function(obj, path, seperator) {

    if (!obj || !path) {
      return;
    }
  
    if (typeof path === "string") {
      path = path.split(seperator);
    }
  
    for (var i = 0; i < path.length - 1; i++) {
  
      obj = obj[path[`${i}`]];
  
      if (typeof obj === "undefined") {
        return;
      }
    }
  
    delete obj[path.pop()];
};

/**
 * Ensures the JSON database folder and file exist.
 * @param {string} dbFolder Database folder.
 * @param {string} dbName Database file name without extension.
 * @returns {void}
 */
module.exports.fetchFiles = function(dbFolder, dbName) {
  const fs = require("fs");
    if (fs.existsSync(`${dbFolder}`) === false){
        fs.mkdirSync(`${dbFolder}`, { recursive: true });
        if(fs.existsSync(`./${dbFolder}/${dbName}.json`) === false) {
            fs.writeFileSync(`./${dbFolder}/${dbName}.json`, "{}");
            return;
        }
    } else {
        if(fs.existsSync(`./${dbFolder}/${dbName}.json`) === false) {
            fs.writeFileSync(`./${dbFolder}/${dbName}.json`, "{}");
        }
    }

};

/**
 * Removes empty objects recursively without removing stored falsey values.
 * @param {Object} obj Target object.
 * @returns {boolean} True when any empty object was removed.
 */
module.exports.removeEmptyData = function (obj) {
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return false;
  var changed = false;

  Object.keys(obj).forEach(function(key) {
    var value = obj[`${key}`];
    if (value && typeof value === "object" && !Array.isArray(value)) {
      if (module.exports.removeEmptyData(value)) {
        changed = true;
      }
      if (Object.keys(value).length === 0) {
        delete obj[`${key}`];
        changed = true;
      }
    }
  });

  return changed;
};
